  ('5470e2bc-8a94-4531-8c54-0ea913615eaa', '114學年度第2學期清寒學生助學暨生活津貼補助', '國立臺北大學學務處生活輔導組', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3871', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3871', '國立臺北大學校內獎學金', 'school_public_scholarship_page', null, '2026-06-30T04:00:45.919Z'::timestamptz, 'f49041554084e8b7cc947638cf795f8b91caed36aefe8f02d7ae696168acd293', 'ntpu_scholarship_internal:https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3871', '2026-04-01'::date, '獎學金', array['不限／不適用']::text[], array['校內獎學金', '清寒助學', '學業表現']::text[], array['寫作']::text[], array['申請表', '證明文件']::text[], array['申請表', '成績單', '證明文件']::text[], '本校學士班及進修學士班學生，限大二以上學生申請；1.助學金：前學期學業成績70分以上、操行成績80分以上家境清寒者。 2.生活津貼補助金： (1)前學期學業成績60分以上、操行成績80分以上者。 (2)具有政府低收入戶證明者。 3.助學金及生活津貼補助金每學期每人限擇一申請，且未享公費待遇者', '國立臺北大學', '不限', '大二以上', '獎學金 3000元', array['獎金']::text[], 3000, '提供清寒學生助學金或生活津貼，需檢附成績與清寒或低收入戶相關證明。', array['此獎學金已截止，保留作為資料展示與流程測試。', '申請方式：4/1下午5點前申請資料送生輔組辦理，逾時不予受理', '附件與完整規則請以官方獎學金頁面為準。']::text[], '4/1下午5點前申請資料送生輔組辦理，逾時不予受理', '[{"date":"2026-04-01","label":"申請截止"}]'::jsonb, '1.助學金：前學期學業成績70分以上、操行成績80分以上家境清寒者。 2.生活津貼補助金： (1)前學期學業成績60分以上、操行成績80分以上者。 (2)具有政府低收入戶證明者。 3.助學金及生活津貼補助金每學期每人限擇一申請，且未享公費待遇者', 'published'),
  ('40f5cbbb-22ed-44b1-8496-e63622e4d909', '114-2國立臺北大學村騫希望獎助學金', '國立臺北大學學務處生活輔導組', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3852', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3852', '國立臺北大學校內獎學金', 'school_public_scholarship_page', null, '2026-06-30T04:00:45.919Z'::timestamptz, '77f1004624b2a98165cf808753c96a010943cbd8f7c77b72168702a8460ae8c8', 'ntpu_scholarship_internal:https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3852', '2026-04-10'::date, '獎學金', array['不限／不適用']::text[], array['校內獎學金', '清寒助學', '學業表現']::text[], array['寫作']::text[], array['申請表', '證明文件']::text[], array['申請表', '成績單', '證明文件', '推薦資料']::text[], '學士班、進修學士班及碩、博士班學生。(具114年度清寒證明之僑生;本地生須符合高教深耕以下四類--低收入戶、中低收入戶、特殊境遇家庭子女及本年度符合教育部弱勢助學金補助之學生申請)；1.上學期平均成績學士班應達75分以上（分數未到不受理），碩、博士班應達80分以上且無不及格之科目。 2.家境清寒（具114年度清寒證明之僑生;本地生須符合高教深耕以下四類--低收入戶、中低收入戶、特殊境遇家庭子女及本年度符合教育部弱勢助學金補助之學生，不含村里長清寒證明）。 3.深耕圓夢（飛鳶組）同學及延畢、重修學生請勿申請) 4.僅能提供村里長清寒證明者請勿申請 5.列年度教育部弱勢助學金名單同學可申請', '國立臺北大學', '依官方公告', '學士班、碩士班；博士班依公告', '獎學金 5000～25000', array['獎金']::text[], 25000, '提供清寒或弱勢學生獎助，申請時需檢附成績、家庭經濟證明與推薦資料。', array['此獎學金已截止，保留作為資料展示與流程測試。', '申請方式：4/10前送生輔組辦理（逾期與缺件者不收）', '附件與完整規則請以官方獎學金頁面為準。']::text[], '4/10前送生輔組辦理（逾期與缺件者不收）', '[{"date":"2026-04-10","label":"申請截止"}]'::jsonb, '1.上學期平均成績學士班應達75分以上（分數未到不受理），碩、博士班應達80分以上且無不及格之科目。 2.家境清寒（具114年度清寒證明之僑生;本地生須符合高教深耕以下四類--低收入戶、中低收入戶、特殊境遇家庭子女及本年度符合教育部弱勢助學金補助之學生，不含村里長清寒證明）。 3.深耕圓夢（飛鳶組）同學及延畢、重修學生請勿申請) 4.僅能提供村里長清寒證明者請勿申請 5.列年度教育部弱勢助學金名單同學可申請', 'published'),
  ('8ce9ed98-e071-422d-947d-9e87c950aa8c', '財團法人麗裕慈善基金會', '國立臺北大學學務處生活輔導組', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3851', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3851', '國立臺北大學校內獎學金', 'school_public_scholarship_page', null, '2026-06-30T04:00:45.919Z'::timestamptz, '6533fc307dc3489403cae8d334aa5bb672c4d89d259d06e586dfa66a7cdbf8bd', 'ntpu_scholarship_internal:https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3851', null, '獎學金', array['不限／不適用']::text[], array['校內獎學金', '清寒助學', '學業表現']::text[], array['寫作']::text[], array['證明文件', '短文']::text[], array['成績單', '證明文件', '自傳', '推薦資料']::text[], '就讀本校各學系學士班之在學學生(不含進修學士班)，法律學院、商學院、公共事務學院、社會科學院、人文學院，以及電機資訊學院等各1名，合計每學年6名。(需經由各院推薦1名)；學士班二年級以上學生 (一）凡就讀本校學士班之學生符合下列具體事蹟者： 1.遵行孝道、實踐孝悌，有具體事實者。 2.家境清寒、半工半讀、協助家計，有具體事實者。 3. 其他具體文件足資證明確有堪為楷模之孝行事實或彰顯社 會良善行為者。 (二）符合前述申請資格但有下列情事之一者，不得申請本獎學金： 1.前學年學業成績有不及格紀錄者。 2.前學年操行有懲處紀錄者。', '國立臺北大學', '不限', '學士班', '獎學金 1萬元', array['獎金']::text[], 10000, '由各學院推薦具孝行、清寒或社會良善事蹟之學士班學生申請。', array['申請方式：欲申請同學請由各院審核後推薦', '附件與完整規則請以官方獎學金頁面為準。']::text[], '欲申請同學請由各院審核後推薦', '[]'::jsonb, '學士班二年級以上學生 (一）凡就讀本校學士班之學生符合下列具體事蹟者： 1.遵行孝道、實踐孝悌，有具體事實者。 2.家境清寒、半工半讀、協助家計，有具體事實者。 3. 其他具體文件足資證明確有堪為楷模之孝行事實或彰顯社 會良善行為者。 (二）符合前述申請資格但有下列情事之一者，不得申請本獎學金： 1.前學年學業成績有不及格紀錄者。 2.前學年操行有懲處紀錄者。', 'published'),
