  ('a8a14c92-f1b5-4591-9188-0946dafa1d27', '114學年度臺北大學何志欽校長資優暨育成獎學金', '國立臺北大學學務處生活輔導組', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3848', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3848', '國立臺北大學校內獎學金', 'school_public_scholarship_page', null, '2026-06-30T04:00:45.919Z'::timestamptz, '424b9c7d69642fc45912eec9705c821d349702d3d657d55b868289df09d5e3c4', 'ntpu_scholarship_internal:https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3848', '2026-03-31'::date, '獎學金', array['語言／國際']::text[], array['校內獎學金', '清寒助學', '國際交流', '學業表現']::text[], array['寫作']::text[], array['申請表', '證明文件', '短文']::text[], array['申請表', '成績單', '證明文件', '自傳']::text[], '資優獎學金：本校在學學士班學生。（不含延畢生）（因經費受限，本年度育成獎學金停辦，請同學切勿申請該項）；1.資優獎學金，前學年學業成績平均85分（含）以上且為全班排名前二 名者。（大一學生為前一學期成績） 2.未受公費待遇及未領有其他校內外獎助學金超過5萬元者。 3.具清寒、弱勢（特殊境遇家庭、原住民..等）、社會服務志工及國際 性活動或研習等證明將列入資優獎學金特別加分項目。', '國立臺北大學', '不限', '學士班', '獎學金 50000元', array['獎金']::text[], 50000, '提供學業表現優秀之學士班學生申請，清寒、弱勢或服務經歷可作為加分資料。', array['此獎學金已截止，保留作為資料展示與流程測試。', '申請方式：3/31下午5點前申請資料送生輔組辦理，逾時不予受理', '附件與完整規則請以官方獎學金頁面為準。']::text[], '3/31下午5點前申請資料送生輔組辦理，逾時不予受理', '[{"date":"2026-03-31","label":"申請截止"}]'::jsonb, '1.資優獎學金，前學年學業成績平均85分（含）以上且為全班排名前二 名者。（大一學生為前一學期成績） 2.未受公費待遇及未領有其他校內外獎助學金超過5萬元者。 3.具清寒、弱勢（特殊境遇家庭、原住民..等）、社會服務志工及國際 性活動或研習等證明將列入資優獎學金特別加分項目。', 'published'),
  ('ca71c8dc-247d-4e72-8246-a7eafced500e', '國立臺北大學114學年度「張平沼先生暨陳淑珠女士獎學金」', '國立臺北大學學務處生活輔導組', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3808', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3808', '國立臺北大學校內獎學金', 'school_public_scholarship_page', null, '2026-06-30T04:00:45.919Z'::timestamptz, 'aecfa8a5e9afc7a66a9c1c83bc66d2e18b98626eb28b40684dc1edc80aeaac66', 'ntpu_scholarship_internal:https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3808', '2025-11-24'::date, '獎學金', array['不限／不適用']::text[], array['校內獎學金', '清寒助學', '學業表現']::text[], array['寫作']::text[], array['申請表', '證明文件', '短文']::text[], array['申請表', '成績單', '證明文件', '自傳']::text[], '本校具正式學籍之博碩士班、學士班、進修學士班之本地生、僑生（因新生無前學期在校成績故不含）。；1.前一學年學業成績平均達80分以上，操行成績80分以上。 2.領有政府機關核發之低（中）收入戶證明或家庭遭受重大變故者為優先。 3.當學期未領其他獎助學金超過5萬元者。', '國立臺北大學', '不限', '學士班、碩士班；博士班依公告', '獎學金 50000元', array['獎金']::text[], 50000, '提供本校具正式學籍學生申請，清寒或家庭重大變故者優先。', array['此獎學金已截止，保留作為資料展示與流程測試。', '申請方式：11/24下午5時前送生輔組辦理（逾期與缺件者不收）', '附件與完整規則請以官方獎學金頁面為準。']::text[], '11/24下午5時前送生輔組辦理（逾期與缺件者不收）', '[{"date":"2025-11-24","label":"申請截止"}]'::jsonb, '1.前一學年學業成績平均達80分以上，操行成績80分以上。 2.領有政府機關核發之低（中）收入戶證明或家庭遭受重大變故者為優先。 3.當學期未領其他獎助學金超過5萬元者。', 'published'),
  ('6eee1d31-512a-4a33-8b92-ee533ec42ee7', '114-1國立臺北大學村騫希望獎助學金', '國立臺北大學學務處生活輔導組', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3790', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3790', '國立臺北大學校內獎學金', 'school_public_scholarship_page', null, '2026-06-30T04:00:45.919Z'::timestamptz, '499aae170b0eeb20b4c4ec9872b5a2ae454eb5bf43c1ebf1c578a91866fb3f1f', 'ntpu_scholarship_internal:https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3790', '2025-11-03'::date, '獎學金', array['不限／不適用']::text[], array['校內獎學金', '清寒助學', '學業表現']::text[], array['寫作']::text[], array['申請表', '證明文件']::text[], array['申請表', '成績單', '證明文件', '推薦資料']::text[], '學士班、進修學士班及碩、博士班學生。(具114年度清寒證明之僑生;本地生須符合高教深耕以下四類--低收入戶、中低收入戶、特殊境遇家庭子女及本年度符合教育部弱勢助學金補助之學生申請)；1.上學期平均成績學士班應達75分以上（分數未到不受理），碩、博士班應達80分以上且無不及格之科目。 2.家境清寒（具114年度清寒證明之僑生;本地生須符合高教深耕以下四類--低收入戶、中低收入戶、特殊境遇家庭子女及本年度符合教育部弱勢助學金補助之學生，不含村里長清寒證明）。 3.深耕圓夢（飛鳶組）同學及延畢、重修學生請勿申請) 4.僅能提供村里長清寒證明者請勿申請 5.列年度教育部弱勢助學金名單同學可申請', '國立臺北大學', '依官方公告', '學士班、碩士班；博士班依公告', '獎學金 5000～25000', array['獎金']::text[], 25000, '提供清寒或弱勢學生獎助，申請時需檢附成績、家庭經濟證明與推薦資料。', array['此獎學金已截止，保留作為資料展示與流程測試。', '申請方式：11/3前送生輔組辦理（逾期與缺件者不收）', '附件與完整規則請以官方獎學金頁面為準。']::text[], '11/3前送生輔組辦理（逾期與缺件者不收）', '[{"date":"2025-11-03","label":"申請截止"}]'::jsonb, '1.上學期平均成績學士班應達75分以上（分數未到不受理），碩、博士班應達80分以上且無不及格之科目。 2.家境清寒（具114年度清寒證明之僑生;本地生須符合高教深耕以下四類--低收入戶、中低收入戶、特殊境遇家庭子女及本年度符合教育部弱勢助學金補助之學生，不含村里長清寒證明）。 3.深耕圓夢（飛鳶組）同學及延畢、重修學生請勿申請) 4.僅能提供村里長清寒證明者請勿申請 5.列年度教育部弱勢助學金名單同學可申請', 'published'),
  ('3d59db1d-2619-4f65-829f-3d6f1e269adf', '國立臺北大學校友-李厚高先生紀念獎學金', '國立臺北大學學務處生活輔導組', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3762', 'https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3762', '國立臺北大學校內獎學金', 'school_public_scholarship_page', null, '2026-06-30T04:00:45.919Z'::timestamptz, '81b2e8f24ed271d65f9215ccff9798d84418821ba56738e39a76061229c24215', 'ntpu_scholarship_internal:https://webap.ntpu.edu.tw/scholarship/scholarship_more.php?id=3762', '2025-10-16'::date, '獎學金', array['不限／不適用']::text[], array['校內獎學金', '清寒助學', '學業表現']::text[], array['寫作']::text[], array['申請表', '證明文件']::text[], array['申請表', '成績單', '證明文件']::text[], '本校日間部學士班學生。(不含大一新生)；1.家境清寒須附清寒證明或由班導師書面證明。 2.未受公費待遇。', '國立臺北大學', '不限', '大二以上', '獎學金 5000元', array['獎金']::text[], 5000, '限日間部學士班學生申請，需檢附清寒證明或導師書面證明。', array['此獎學金已截止，保留作為資料展示與流程測試。', '申請方式：10/16下午5點前資料送生輔組辦理(逾時、資料不全不予受理)', '附件與完整規則請以官方獎學金頁面為準。']::text[], '10/16下午5點前資料送生輔組辦理(逾時、資料不全不予受理)', '[{"date":"2025-10-16","label":"申請截止"}]'::jsonb, '1.家境清寒須附清寒證明或由班導師書面證明。 2.未受公費待遇。', 'published')
